const home='<main><section class="hero"><div class="wrap heroGrid"><div><div class="eyebrow">Publishing · Editing · Writing · Book Promotion</div><h1>Helping Authors Rise Through Better Publishing, Positioning & Promotion.</h1><p>BookRise Centre brings publishing, editorial, design and book-promotion expertise together to help authors prepare their work, make informed decisions and connect with relevant readers.</p><div class="actions">'+btn('/contact','Discuss Your Book')+btn('/services','Explore Our Services',true)+'</div></div><div class="heroArt heroPhoto"><img src="https://images.unsplash.com/photo-1769794371055-54436b54577e?auto=format&fit=crop&fm=jpg&ixlib=rb-4.1.0&q=82&w=1200" alt="A publishing workspace with open books, manuscript notes, editing pens and reference books" width="1200" height="1800" fetchpriority="high"></div></div></section><section class="section white"><div class="wrap"><div class="heading"><div class="kicker">A considered approach</div><h2>One Centre. Multiple Areas of Expertise.</h2><p class="lead">Publishing is more than a single task. Manuscript quality, book design, platform preparation, positioning and reader outreach each play a role. BookRise Centre brings these areas together through a coordinated, author-focused service model.</p></div><div class="grid3"><article class="card"><small>01 / EXPERTISE</small><h3>A Connected Team</h3><p>Skills across publishing, literary direction, marketing and reader promotion, coordinated around each book.</p></article><article class="card"><small>02 / PARTNERSHIP</small><h3>Project-Led</h3><p>Recommendations are shaped around the book, the author’s priorities and its intended readership.</p></article><article class="card"><small>03 / OWNERSHIP</small><h3>Clear Agreements</h3><p>Scope, deliverables, responsibilities and ownership terms are set out before work begins.</p></article></div><div class="stats"><div class="stat"><strong>Four</strong><span>Specialists</span></div><div class="stat"><strong>Author-first</strong><span>Project approach</span></div><div class="stat"><strong>Author IP</strong><span>Ownership retained</span></div><div class="stat"><strong>Seven</strong><span>Service areas</span></div></div></section><section class="section"><div class="wrap"><div class="heading"><div class="kicker">Our services</div><h2>From manuscript to meaningful visibility.</h2><p class="lead">A connected range of services for the decisions and practical work that arise before and after publication.</p></div><div class="grid3">'+homeServiceCards+'</div><p style="margin-top:28px">'+btn('/services','')+'</p></div></section><section class="section white"><div class="wrap split"><div><div class="kicker">Our philosophy</div><h2>Better books deserve thoughtful support.</h2><p class="lead">We bring literary direction, publishing knowledge and promotional thinking together while keeping the author’s voice, ownership and objectives at the center of the process. Our role is to clarify options, agree practical deliverables and carry out the work set out for each project.</p>'+btn('/about','Discover BookRise Centre')+'</div><div class="pullquote">“Our work begins with understanding the book and the author. Every recommendation should serve the project’s real needs, not a one-size-fits-all package.”</div></div></section><section class="section"><div class="wrap"><div class="heading"><div class="kicker">Selected projects</div><h2>Books and the people behind them.</h2><p class="lead">A selection of titles and author projects supported by BookRise Centre.</p></div><div class="grid3">'+bookCards+'</div><p style="margin-top:25px">'+btn('/work','Explore Our Work')+'</p></div></section><section class="section white"><div class="wrap"><div class="heading"><div class="kicker">Author experiences</div><h2>What authors say about working with us.</h2><p class="lead">Feedback from authors whose projects are featured here.</p></div><div class="grid3">'+reviewCards+'</div></div></section>'+cta+'</main>';
const about='<main>'+intro('About BookRise Centre','Bringing publishing expertise together around authors.','An author-services team built around editorial quality, clear agreements and respect for creative ownership.')+'<section class="section"><div class="wrap split"><div><div class="kicker">Who we are</div><h2>Thoughtful support. A shared commitment to authors.</h2><p class="lead">BookRise Centre supports authors with the editorial, publishing and promotional work involved in preparing and positioning a book. Led by Gracious J. Literary, our team brings together expertise in literary direction, editing, writing, cover design, marketing and reader outreach. Authors work with one coordinated team while retaining control of their creative work and publishing decisions.</p></div><div class="pullquote">“The author’s goals, creative voice and ownership remain central to every decision we help them make.”</div></div></section><section class="section white"><div class="wrap"><div class="heading"><div class="kicker">Our principles</div><h2>What guides our work.</h2></div><div class="grid3"><article class="card"><small>01 / CLARITY</small><h3>Clear expectations</h3><p>We discuss the proposed scope, fees, deliverables, timelines and responsibilities before a project begins.</p></article><article class="card"><small>02 / CRAFT</small><h3>Respect for the work</h3><p>We approach each manuscript and book project with attention to its subject, audience, voice and intended presentation.</p></article><article class="card"><small>03 / INDEPENDENCE</small><h3>Author ownership</h3><p>Our service model is built around professional support, not acquiring an author’s intellectual property or royalties.</p></article></div></div></section>'+cta+'</main>';
const servicesPage='<main>'+intro('Our Services','Specialist support for every stage of your book journey.','Explore the seven areas of support available through BookRise Centre. Services can be commissioned individually or combined when a project needs a coordinated approach.')+'<section class="section"><div class="wrap"><div class="grid2">'+serviceCards+'</div><div class="notice" style="margin-top:25px">The exact deliverables, revision rounds, schedule and fee are confirmed in writing for each project. Services are not considered included unless they appear in the agreed scope.</div></div></section>'+cta+'</main>';
const teamPage='<main>'+intro('Our Team','Complementary expertise. One author-focused team.','Our team combines experience in publishing, literary development, book marketing and reader outreach.')+'<section class="section"><div class="wrap"><div class="grid2">'+teamCards+'</div><p class="lead" style="margin-top:28px">Project responsibilities are coordinated around the services agreed with each author and the needs of the book.</p></div></section>'+cta+'</main>';
const workPage='<main>'+intro('Selected Work','Every book has its own voice. Every project deserves its own approach.','Explore selected author projects represented in the BookRise Centre portfolio.')+'<section class="section"><div class="wrap"><div class="grid3">'+bookCards+'</div></div></section><section class="section white"><div class="wrap"><div class="heading"><div class="kicker">Author feedback</div><h2>Experiences shared by authors.</h2></div><div class="grid3">'+reviewCards+'</div></div></section>'+cta+'</main>';
const authorsPage='<main>'+intro('For Authors','Your book. Your rights. A clearer path forward.','Professional support shaped around your manuscript, publishing ambitions and intended readership.')+'<section class="section"><div class="wrap"><div class="heading"><div class="kicker">Author partnership</div><h2>Support that starts with listening.</h2><p class="lead">Every book and every author arrives at a different stage. We begin by understanding your project, priorities, timeline and the kind of help you are looking for. From there, we identify relevant services and discuss a practical scope of work.</p></div><div class="grid3"><article class="card"><small>01 / DISCOVERY</small><h3>Share your project</h3><p>Tell us about your book, its current stage, genre, intended readership and what you want to accomplish.</p></article><article class="card"><small>02 / SCOPE</small><h3>Review the recommendation</h3><p>Discuss the services, deliverables, schedule, fees, revision arrangements and any third-party costs relevant to your project.</p></article><article class="card"><small>03 / AGREEMENT</small><h3>Move forward clearly</h3><p>Review and approve the written agreement before work begins. The agreed document sets the expectations for both sides.</p></article></div></div></section><section class="section white"><div class="wrap split"><div><div class="kicker">Your work remains yours</div><h2>Author ownership is fundamental.</h2><p class="lead">BookRise Centre is a paid author-services organization. Authors retain their intellectual property rights. Our fees are for agreed professional services; we do not acquire your rights or take your royalties.</p></div><div class="notice">The project agreement should clearly set out the scope, fees, deliverables, ownership, third-party costs, payment schedule and applicable cancellation or refund terms.</div></div></section><section class="section"><div class="wrap"><div class="heading"><div class="kicker">Before you enquire</div><h2>Helpful information to prepare.</h2><p class="lead">To help us understand your project, include your book title, genre, approximate word count if known, current publishing stage, the services you are considering and your preferred timeline. You do not need to have every detail finalised before making an inquiry.</p></div>'+btn('/contact','Send an Enquiry')+'</div></section>'+cta+'</main>';
const processPage='<main>'+intro('Our Process','A clear process, from first conversation to agreed delivery.','Good collaboration begins with shared expectations, a suitable scope and a clear understanding of what the work will involve.')+'<section class="section"><div class="wrap"><div class="step"><div class="stepNo">01</div><div><h3>Discovery and project understanding</h3><p>We learn about your manuscript or published book, its genre, current stage, intended readership, objectives and the challenges you would like help addressing.</p></div></div><div class="step"><div class="stepNo">02</div><div><h3>Service recommendation and scope</h3><p>We identify relevant areas of support and outline the proposed tasks, deliverables, review points, responsibilities and estimated schedule.</p></div></div><div class="step"><div class="stepNo">03</div><div><h3>Written quotation and agreement</h3><p>You receive the proposed fee and terms. Scope, payment arrangements, deliverables, ownership, third-party costs and applicable cancellation or refund conditions are documented before work begins.</p></div></div><div class="step"><div class="stepNo">04</div><div><h3>Project delivery and communication</h3><p>We carry out the agreed work, communicate around progress and provide the deliverables and review opportunities included in the agreement.</p></div></div><div class="step"><div class="stepNo">05</div><div><h3>Completion and handover</h3><p>At completion, the agreed files, materials or campaign summary are handed over. Any further work is discussed and agreed separately.</p></div></div></div></section>'+cta+'</main>';
const whyPage='<main>'+intro('Why BookRise Centre','Author-focused support, with clear terms and respect for your work.','A coordinated team, a clear service model and respect for the ownership of your work.')+'<section class="section"><div class="wrap"><div class="grid3"><article class="card"><small>01</small><h3>Complementary expertise</h3><p>Publishing, literary, marketing and reader-promotion skills brought together in one organization.</p></article><article class="card"><small>02</small><h3>Coordinated support</h3><p>Authors can discuss connected areas of support without having to approach every specialist separately.</p></article><article class="card"><small>03</small><h3>Transparent terms</h3><p>Scope, fees, deliverables, timelines and responsibilities should be clear before work begins.</p></article><article class="card"><small>04</small><h3>Author ownership</h3><p>Authors retain their intellectual property rights and creative independence.</p></article><article class="card"><small>05</small><h3>Project-led recommendations</h3><p>Service recommendations are discussed in the context of the book and the author’s stated objectives.</p></article><article class="card"><small>06</small><h3>Thoughtful communication</h3><p>Shared expectations and communication are part of the agreed working relationship.</p></article></div></div></section>'+cta+'</main>';
const F=[
["What services does BookRise Centre provide?","We provide publishing support, editing and writing, cover design, book promotion, video promotion and book trailers, visibility and discoverability support, and reader outreach. The exact work available for a project is confirmed during the initial discussion and scoping process."],
["Can I request just one service?","Yes. You may enquire about an individual service or a combination of services. The recommendation depends on your project requirements and the work you want completed."],
["How much do your services cost?","We use project-based quotations rather than publishing a single price for every book. Fees depend on the service, manuscript or campaign requirements, scope, turnaround, deliverables and any external costs. Contact us for a written quotation."],
["Do you offer fixed packages?","A defined package may be discussed where the scope is suitable, but we do not assume every author needs the same combination of services. Any package, inclusions and exclusions must be stated clearly in writing."],
["Does BookRise Centre take ownership of my book?","No. Authors retain their intellectual property rights. The written agreement should confirm ownership and any limited permissions needed to perform the agreed services."],
["Do you take royalties from book sales?","No. BookRise Centre charges for the agreed author services and does not take your book royalties."],
["Do you guarantee book sales, reviews, rankings or media coverage?","No. Sales, reviews, rankings, media coverage and audience response depend on factors outside any service provider’s control. We do not guarantee these outcomes. We focus on carrying out the agreed professional work and reporting on the activity within scope."],
["How do you begin a project?","We start with an enquiry and a discussion of your book, goals and requirements. If the proposed work is suitable, we provide a written scope, quotation and terms for your review."],
["When does work begin?","Work begins after the scope, fees, deliverables, timeline, payment arrangements and applicable terms have been agreed in writing and any required initial payment has been received."],
["Can you work with a book that is already published?","Yes. Authors may enquire about editing, cover updates, metadata and discoverability reviews, promotional planning or reader outreach for an already published title."],
["Will I receive updates during the project?","Communication and review points are agreed as part of the project scope. The agreement should identify the expected contact points and how feedback or approvals will be handled."],
["What information should I include in my enquiry?","Include your name, email, book title if available, genre, current publishing stage, the service you are considering, a short project description and your preferred timeline."]
];
const faqPage='<main>'+intro('Frequently Asked Questions','Helpful answers before you begin.','Clear information about our services, fees, author ownership and the way we work.')+'<section class="section"><div class="wrap">'+F.map((f,i)=>'<div class="faq"><h3>'+String(i+1).padStart(2,'0')+'. '+f[0]+'</h3><p>'+f[1]+'</p></div>').join('')+'</div></section>'+cta+'</main>';
const pricingPage='<main>'+intro('Pricing & Engagement','Clear quotations. Defined deliverables. No one-size-fits-all fees.','BookRise Centre provides paid professional author services. Each quotation is shaped around the work your book actually requires.')+'<section class="section"><div class="wrap"><div class="priceIntro"><div class="kicker">Our pricing approach</div><h2>Every project is scoped before it is priced.</h2><p class="priceNote">Our quotations reflect the scope, complexity and deliverables agreed for each project. We prepare a written proposal after understanding your requirements.</p><p class="lead">The cost of a project depends on the service selected, the size and condition of the manuscript or book materials, the level of work required, the number of deliverables, the turnaround time and any third-party expenses.</p></div><div class="grid3"><article class="card"><small>01 / SERVICE</small><h3>Individual services</h3><p>Request a quotation for a specific task such as proofreading, cover design, metadata review or a promotional campaign. The quote will define exactly what is included.</p></article><article class="card"><small>02 / COMBINED SUPPORT</small><h3>Coordinated projects</h3><p>Where a book needs several kinds of support, we can discuss a combined scope and sequence the work into clear stages.</p></article><article class="card"><small>03 / BESPOKE SCOPE</small><h3>Project-specific proposals</h3><p>For larger or more involved projects, the proposal can set out milestones, deliverables, review points, payment stages and timing.</p></article></div></div></section><section class="section white"><div class="wrap"><div class="heading"><div class="kicker">What shapes a quotation</div><h2>The factors we consider.</h2></div><div class="grid2"><article class="card"><h3>Nature and size of the work</h3><p>Manuscript length, file condition, editing depth, design requirements, number of titles and the amount of material to be reviewed.</p></article><article class="card"><h3>Deliverables and revisions</h3><p>The agreed files, formats, number of concepts or revision rounds, feedback process and final handover requirements.</p></article><article class="card"><h3>Schedule and coordination</h3><p>Requested turnaround, project complexity, approval stages and any coordination required across multiple services.</p></article><article class="card"><h3>External and platform costs</h3><p>Any agreed third-party expenses, such as printing, paid advertising, platform charges or specialist production costs, should be identified separately where applicable.</p></article></div></div></section><section class="section"><div class="wrap split"><div><div class="kicker">Before you approve</div><h2>What your quotation should make clear.</h2><p class="lead">Before payment or commencement, you should be able to see the service description, deliverables, exclusions, fee and payment schedule, estimated timeline, author responsibilities, revision arrangements, ownership terms, external costs and cancellation or refund conditions.</p></div><div class="notice"><strong>Our commitment to transparency</strong><br>We do not guarantee sales, reviews, rankings or commercial results. Any quotation covers the professional services and deliverables specifically described in the written agreement, not an assured market outcome.</div></div></section><section class="section white"><div class="wrap"><div class="heading"><div class="kicker">Request a quotation</div><h2>Tell us what your book needs.</h2><p class="lead">Send your book title, genre, approximate word count if known, publishing stage, the service you are considering and your preferred timeline. We will use those details to understand the project and discuss an appropriate scope.</p></div>'+btn('/contact','Request a Project Quote')+'</div></section>'+cta+'</main>';
const contactPage="<main><section class='intro'><div class='wrap'><div class='crumb'>Contact BookRise Centre</div><h1>Let us start a conversation about your book.</h1><p>Share a few details about your project. Our team will review your inquiry and follow up using the contact information you provide.</p></div></section><section class='section'><div class='wrap contact-layout'><div><div class='kicker'>A considered first step</div><h2>Tell us about the book you are building.</h2><p class='lead'>Whether you are preparing a manuscript, refining a published title or planning a promotional campaign, a little context helps us understand what you need.</p><div class='contactbox'><h3>BookRise Centre</h3><div class='contactline'><span>General inquiries</span><a href='mailto:hello@bookrisecentre.com'>hello@bookrisecentre.com</a></div><div class='contactline'><span>WhatsApp</span><a href='https://wa.me/2349049497206'>+234 904 949 7206</a></div><div class='contactline'><span>Office</span>Brooklyn, New York, United States</div></div><p class='privacy-note'>Please do not include confidential manuscript files at this stage.</p></div><div class='form-panel'><div class='kicker'>Project inquiry</div><h2>How can we support you?</h2><form id='enquiry-form' class='enquiry-form'><div class='form-grid'><label>Full name *<input name='fullName' required maxlength='120'></label><label>Email address *<input name='email' type='email' required maxlength='180'></label><label>Book title<input name='bookTitle' maxlength='180'></label><label>Genre / category<input name='genre' maxlength='120'></label><label>Service required *<select name='service' required><option value=''>Select a service</option><option>Publishing Support</option><option>Editing & Writing</option><option>Cover Design</option><option>Book Promotion</option><option>Video Promotion & Book Trailers</option><option>Visibility & Discoverability</option><option>Reader Outreach</option><option>Multiple Services / Not Sure</option></select></label><label>Publishing stage<select name='projectStage'><option value=''>Select stage</option><option>Planning a book</option><option>Manuscript in progress</option><option>Manuscript completed</option><option>Preparing for publication</option><option>Already published</option></select></label><label class='full'>Preferred timeline<select name='timeline'><option value=''>Select timeline</option><option>As soon as practical</option><option>Within 1 month</option><option>Within 2–3 months</option><option>Flexible</option></select></label><label class='full'>Tell us about your project *<textarea name='message' rows='6' required maxlength='5000'></textarea></label><label class='honeypot'>Leave empty<input name='website' tabindex='-1' autocomplete='off'></label><label class='consent full'><input type='checkbox' name='consent' required><span>I agree that BookRise Centre may use these details to respond to my enquiry. See our <a href='/privacy'>Privacy Policy</a>.</span></label></div><button class='btn submit-btn' type='submit'>Submit Project Enquiry ↗</button><p class='form-status' id='form-status' role='status' aria-live='polite'></p><p class='form-footnote'>Do not include passwords, payment details or sensitive personal information.</p></form></div></div></section></main>";
const legal=(title,desc,sections)=>'<main>'+intro('BookRise Centre · Information',title,desc)+'<section class="section"><div class="wrap legaltext">'+sections.map(s=>'<h2>'+s[0]+'</h2><p>'+s[1]+'</p>').join('')+'</div></section></main>';
const terms=legal('Terms of Service','The principles governing inquiries and paid author-service engagements with BookRise Centre.',[
['1. Services and project scope','BookRise Centre provides professional author services including publishing support, editing and writing, cover design, book promotion, visibility and discoverability support, and reader outreach. The services provided for a particular project are limited to the tasks and deliverables expressly described in the written quotation or service agreement.'],
['2. Quotations and acceptance','A quotation is based on the information available when it is prepared. If the manuscript, project requirements, deliverables or schedule change, the scope and fee may need to be reviewed. Work begins only after the parties have accepted the applicable written terms and any required initial payment has been received.'],
['3. Fees and payment','The quotation or agreement should state the fee, currency, payment stages, due dates and any external costs. Any additional work outside the agreed scope requires a separate written approval and may attract an additional fee.'],
['4. Author materials and responsibilities','Authors are responsible for ensuring that they have the right to provide all manuscripts, images, text and other materials supplied for the project. Authors should provide accurate information, feedback and approvals within the agreed timeframe.'],
['5. Intellectual property and ownership','Authors retain ownership of their original manuscripts and intellectual property. Any limited permission required for BookRise Centre to access, edit, format, design or promote materials is restricted to performing the agreed services. The project agreement should record any third-party assets, licenses or platform terms that apply.'],
['6. Revisions, approvals and delivery','The agreement should state the number and nature of included revision rounds, approval responsibilities, file formats and delivery method. Work requested after approval or beyond the agreed revision allowance may be treated as additional work.'],
['7. Third-party services and platforms','Printing, distribution platforms, advertising platforms, paid placements, software, ISBN services and other third-party providers may have their own fees, rules and terms. Such costs should be identified and approved before they are incurred. BookRise Centre does not control third-party platform decisions or availability.'],
['8. No guaranteed commercial outcomes','BookRise Centre does not guarantee book sales, income, reviews, rankings, media coverage, acceptance by reviewers or podcasts, or a particular audience response. Marketing and outreach outcomes depend on independent decisions and market conditions.'],
['9. Cancellation and refunds','Cancellation, pause and refund arrangements should be stated in the project-specific agreement, including how completed work, committed third-party costs and outstanding payments are handled.'],
['10. Communication and changes','Project updates, review points, response expectations and change requests should be agreed at the outset. Material changes to the project may require a revised scope, fee or timeline.'],
['11. Contact','Questions about these terms or a proposed engagement may be sent to hello@bookrisecentre.com.']
]);
const privacy=legal('Privacy Policy','How BookRise Centre handles information provided through enquiries and service engagements.',[
['1. Information you may provide','Depending on your enquiry, you may provide your name, email address, contact details, book title, genre, manuscript or project information, service preferences and communications with our team.'],
['2. How information is used','Information is used to respond to enquiries, assess requested services, prepare quotations, communicate about projects, deliver agreed services and maintain relevant business records.'],
['3. Sharing and service providers','Information may be shared with team members or service providers only where reasonably necessary to respond to an enquiry or perform agreed work. Any third-party platform or provider may process information under its own terms and privacy practices.'],
['4. Manuscripts and confidential material','Please do not send a complete manuscript or sensitive personal information through an unsecured channel before the submission method and any applicable confidentiality arrangements have been discussed and agreed.'],
['5. Retention and security','Information is retained for as long as reasonably necessary for the purpose for which it was provided, relevant project administration and legitimate record-keeping. Appropriate care should be taken to protect information, although no method of electronic transmission or storage can be guaranteed to be completely secure.'],
['6. Your questions and requests','You may contact BookRise Centre to ask about information you have provided or to request an update where appropriate. We may need to retain certain records for legitimate business or legal purposes.'],
['7. Policy updates and contact','This policy may be updated as the Centre’s practices or applicable requirements change. For questions about this policy or requests concerning information you have provided, contact hello@bookrisecentre.com.']
]);
const refunds=legal('Refund & Cancellation Policy','How cancellation and refund arrangements are addressed for BookRise Centre author services.',[
['1. Written terms before payment','Before a project begins, the author should receive written information describing the services, deliverables, total fee, payment schedule, estimated timeline, cancellation process and any applicable refund conditions.'],
['2. Project-specific arrangements','Refund eligibility and cancellation arrangements depend on the agreement for the particular project, the nature of the service, work already completed, resources committed and third-party costs already incurred.'],
['3. Work already completed','Where a project is cancelled after work has started, the agreement should explain how completed work, work in progress and any non-recoverable external costs are accounted for.'],
['4. Third-party charges','Charges paid or committed to independent platforms, suppliers, advertising providers, printers or other third parties may be subject to their own refund rules. Such costs should be disclosed and approved where applicable.'],
['5. Requesting a cancellation or clarification','Authors should submit cancellation requests or questions in writing to hello@bookrisecentre.com, identifying the project and the relevant agreement. The team can then review the applicable terms and respond.'],
['6. Governing agreement','This page provides general information. The project-specific written agreement and any mandatory consumer protections applicable to the transaction govern the final cancellation and refund position.']
]);
const resourcesPage="<main><section class='intro'><div class='wrap'><div class='crumb'>The Author Desk</div><h1>Author Resources</h1><p>Practical guidance to help authors make confident, well-informed publishing decisions.</p></div></section><section class='section'><div class='wrap'><div class='heading'><div class='kicker'>A more informed publishing journey</div><h2>Guidance for each stage of the journey.</h2></div><div class='grid3'><article class='resource-card'><span>01 · BEFORE YOU PUBLISH</span><h3>Manuscript readiness checklist</h3><p>Review structure, consistency, formatting, permissions and final proofing before production.</p><a href='/contact'>Discuss manuscript preparation ↗</a></article><article class='resource-card'><span>02 · BOOK PRESENTATION</span><h3>What makes a strong book cover?</h3><p>Understand genre expectations, title hierarchy, thumbnail legibility and positioning.</p><a href='/services'>Explore cover design ↗</a></article><article class='resource-card'><span>03 · PUBLISHING DECISIONS</span><h3>Choosing a publishing platform</h3><p>Compare distribution options, file requirements, royalties, territories and metadata.</p><a href='/authors'>Read our author approach ↗</a></article><article class='resource-card'><span>04 · DISCOVERABILITY</span><h3>Metadata, categories and keywords</h3><p>Learn how clear descriptions and relevant metadata help readers understand a title.</p><a href='/services'>Explore discoverability ↗</a></article><article class='resource-card'><span>05 · AUTHOR OWNERSHIP</span><h3>Protecting creative independence</h3><p>Clarify intellectual property, service agreements, licenses and third-party costs.</p><a href='/why-choose-us'>Our transparency standard ↗</a></article><article class='resource-card'><span>06 · PROMOTION</span><h3>Planning thoughtful outreach</h3><p>Set realistic goals and identify relevant reader communities for a book campaign.</p><a href='/services'>Explore book promotion ↗</a></article></div></div></section></main>";
